Algorithm SinLluvia
  Dimension dias[10] As Integer;
  For i <- 0 To 9 Do
    Read dias[i];
  EndFor
  Define racha As Integer <- 0;
  Define masLarga As Integer <- 0;
  For Each llovio In dias Do
    If llovio = 0 Then
      racha <- racha + 1;
      If racha > masLarga Then
        masLarga <- racha;
      EndIf
    Else
      racha <- 0;
    EndIf
  EndFor
  Write masLarga;
EndAlgorithm
